/// Builds the program. The game holds the result in a static; building is deterministic.
pub fn build_program() -> Program {
    let mut b = ProgramBuilder::new();
    for (i, name) in VAR_NAMES.iter().enumerate() {
        let v = b.var(*name);
        assert_eq!(v, Var(FIRST_USER_VAR + i as u16), "user variables are numbered in order");
    }
    for name in GLOBAL_NAMES {
        b.global(name);
    }
    for &(id, name, parent, sprite, mask, solid, visible, persistent, depth) in OBJECTS {
        let info = ObjectInfo {
            name: name.into(),
            parent: u32::try_from(parent).ok().map(ObjectId),
            sprite,
            mask,
            solid,
            visible,
            persistent,
            depth,
        };
        b.object(ObjectId(id), info);
    }
    for &(id, event, f) in EVENTS {
        b.event(ObjectId(id), event, f);
    }
    for &(id, vars) in LAYOUTS {
        b.layout(ObjectId(id), vars);
    }
    // TODO(851-3127): GM8's collision stage.
    b.build()
}
